def make_part(question, status, answer=None, sources=None, missing_material=None):
    return {
        "question": question,
        "status": status,
        "answer": answer,
        "sources": list(sources or []),
        "missing_material": list(missing_material or []),
    }

from schemas import make_part


def answer_parts(parts, retrieve, generate):
    results = []
    supported_count = 0

    for question in parts:
        sources = retrieve(question)
        if sources:
            answer = generate(question, sources)
            results.append(make_part(question, "answered", answer, sources))
            supported_count += 1
        else:
            results.append(
                make_part(
                    question,
                    "insufficient_evidence",
                    None,
                    sources,
                    [question],
                )
            )

    if supported_count == len(parts):
        status = "answered"
    elif supported_count == 0:
        status = "insufficient_evidence"
    else:
        status = "partial"

    return {"status": status, "parts": results}
